    [UnidadMedidaId], [ImpuestoId], [Tipo], [Costo], [PrecioMinimo], [CantidadMinimaMayor], [PesoEmpaque],
    [RutaImagen], [EsServicio], [MostrarEnCatalogo], [VentaEnPos], [Activo], [ModificadoEn], [ModificadoPor],
    [PrecioDetalle], [PrecioMayor], [PreciosVigentesDesde])
SELECT NEXT VALUE FOR [SecuenciaArticulos], o.Codigo, o.Descripcion, o.Referencia, d.Id, c.Id, m.Id,
    u.Id, i.Id, o.Tipo, o.Costo, NULL, NULL, NULL,
    NULL, 0, 0, 1, o.Activo, SYSDATETIMEOFFSET(), N'Migración',
    o.PrecioDetalle, o.PrecioMayor, SYSDATETIMEOFFSET()
FROM #Articulos o
JOIN [Departamentos] d ON d.Codigo = o.DepartamentoCodigo
-- Con APPLY se toma siempre una sola fila, aunque la base tenga dos unidades o dos marcas que se llamen igual.
CROSS APPLY (SELECT TOP 1 x.Id FROM [UnidadesMedida] x WHERE x.Abreviatura = o.UnidadAbreviatura ORDER BY x.Id) u
CROSS APPLY (SELECT TOP 1 x.Id FROM [Impuestos] x WHERE x.Codigo = o.ImpuestoCodigo ORDER BY x.Id) i
OUTER APPLY (SELECT TOP 1 x.Id FROM [Categorias] x WHERE x.Codigo = o.CategoriaCodigo ORDER BY x.Id) c
OUTER APPLY (SELECT TOP 1 x.Id FROM [Marcas] x WHERE x.Nombre = o.MarcaNombre ORDER BY x.Id) m
WHERE NOT EXISTS (SELECT 1 FROM [Articulos] a WHERE a.Codigo = o.Codigo);
GO

/* Lo que no se pudo cargar por faltarle su departamento, unidad o impuesto. Si sale algo, revise
   que haya ejecutado los scripts anteriores. */
SELECT o.Codigo, o.Descripcion, o.DepartamentoCodigo, o.UnidadAbreviatura, o.ImpuestoCodigo
FROM #Articulos o
WHERE NOT EXISTS (SELECT 1 FROM [Articulos] a WHERE a.Codigo = o.Codigo);
GO

DROP TABLE #Articulos;
GO

DECLARE @total int = (SELECT COUNT(*) FROM [Articulos]);
PRINT 'Artículos: ' + CAST(@total AS varchar(10)) + ' en total.';
GO
